select bc.id,
       bi.book_name       as bookName,
       bc.chapter_name    as chapterName,
       bc.chapter_content as chapterContent,
       bc.word_count      as wordCount
from book_chapter bc
         inner join book_info bi on bc.book_id = bi.id
